    import random
    import time

    LANGUAGE_WRAPPER = 'Let $a$ and $b$ be integers such that the polynomial $x^2 - {K}x - 1$ is a factor of the polynomial $ax^{{n}} + bx^{{m}} + {C}$. Find the value of $a$.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
while True:
    K = rng.randint(1, 3)
    k = rng.randint(2, 4)
    m_factor = rng.randint(3, 5)
    n = m_factor * k
    m = n - k
    C = rng.randint(1, 5) * rng.choice([-1, 1])

    if n > 20:
        continue

    def lucas_U(val, K_val):
        if val == 0: return 0
        if val == 1: return 1
        a, b = 0, 1
        for _ in range(val - 1):
            a, b = b, K_val * b + a
        return b

    L_k = lucas_U(k, K)
    L_m = lucas_U(m, K)

    sign = 1 if m % 2 == 0 else -1

    if (C * sign * L_m) % L_k != 0:
        continue

    a = (C * sign * L_m) // L_k

    if abs(a) < 2 or abs(a) > 2000:
        continue

    return {
        'K': K,
        'n': n,
        'm': m,
        'C': C
    }

    def verifier(assign):
K = assign['K']
n = assign['n']
m = assign['m']
C = assign['C']

if not (isinstance(K, int) and isinstance(n, int) and isinstance(m, int) and isinstance(C, int)):
    return False, None # Types must be integers

if n <= m or m <= 0:
    return False, None # Exponents must be positive and ordered

k = n - m
if k < 1:
    return False, None # Difference in exponents must be at least 1

if n % k != 0:
    # This is the crucial condition for integer coefficients a and b.
    # The problem implies such integers exist, so this must hold.
    return False, None

# The sequence L_i(K) is a Lucas sequence of the first kind, U_i(K, -1).
# L_0 = 0, L_1 = 1, L_i = K*L_{i-1} + L_{i-2}
def lucas_U(val, K_val):
    if val < 0: return 0
    if val == 0: return 0
    if val == 1: return 1
    a, b = 0, 1
    for _ in range(val - 1):
        a, b = b, K_val * b + a
        if abs(b) > 10**18: return float('inf') # Safety check
    return b

L_k = lucas_U(k, K)
L_m = lucas_U(m, K) # m = n-k

if L_k == 0:
    return False, None # Avoid division by zero (L_k > 0 for k>=1, K>=1)

# The formula for 'a' is a = C * (-1)^(n-k) * L_{n-k} / L_k = C * (-1)^m * L_m / L_k
sign = 1 if m % 2 == 0 else -1

if (C * sign * L_m) % L_k != 0:
    # 'a' would not be an integer. Problem statement guarantees integer a, b.
    return False, None

answer = (C * sign * L_m) // L_k

# For full verification, check that 'b' is also an integer.
# b = C * (-1)^(m+1) * L_n / L_k
L_n = lucas_U(n, K)
sign_b = -sign
if (C * sign_b * L_n) % L_k != 0:
    # 'b' would not be an integer.
    return False, None

if abs(answer) < 2:
    return False, None # Avoid trivial answers

return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
